/**
 * DOMPurify - Enhanced Sanitization Implementation
 * Version: 1.0.0 (Custom Implementation)
 * Secure HTML sanitization for Markdown content
 */
var DOMPurify = (function() {
    'use strict';

    // Default configuration
    const DEFAULT_CONFIG = {
        ALLOWED_TAGS: [
            // Text structure
            'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
            'p', 'br', 'hr', 'div', 'span',
            // Text formatting
            'strong', 'b', 'em', 'i', 'u', 's', 'del', 'ins', 'mark',
            'sub', 'sup', 'small', 'abbr', 'cite', 'dfn', 'kbd', 'samp', 'var',
            // Code
            'code', 'pre',
            // Links and media
            'a', 'img',
            // Lists
            'ul', 'ol', 'li',
            // Quotes
            'blockquote', 'q',
            // Tables
            'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td', 'caption', 'colgroup', 'col',
            // Details/Summary
            'details', 'summary',
            // Other semantic elements
            'figure', 'figcaption', 'article', 'section', 'aside', 'header', 'footer', 'nav', 'main',
            // Form elements (for task lists)
            'input', 'label',
            // Definition lists
            'dl', 'dt', 'dd',
            // Ruby annotations
            'ruby', 'rt', 'rp'
        ],
        ALLOWED_ATTR: [
            // Global attributes
            'id', 'class', 'title', 'lang', 'dir',
            // Links
            'href', 'target', 'rel',
            // Images
            'src', 'alt', 'width', 'height', 'loading',
            // Tables
            'colspan', 'rowspan', 'scope', 'headers',
            // Form elements
            'type', 'checked', 'disabled', 'readonly',
            // Accessibility
            'aria-label', 'aria-labelledby', 'aria-describedby', 'aria-hidden', 'role',
            // Data attributes (for custom styling)
            'data-*',
            // Style (controlled)
            'style'
        ],
        // Dangerous tags to always remove
        FORBID_TAGS: [
            'script', 'style', 'iframe', 'object', 'embed', 'form', 
            'applet', 'meta', 'link', 'base', 'frame', 'frameset',
            'svg', 'math', 'template', 'noscript', 'canvas'
        ],
        // Dangerous attributes to always remove
        FORBID_ATTR: [
            'onclick', 'ondblclick', 'onmousedown', 'onmouseup', 'onmouseover',
            'onmousemove', 'onmouseout', 'onmouseenter', 'onmouseleave',
            'onkeydown', 'onkeypress', 'onkeyup',
            'onload', 'onerror', 'onabort', 'onunload', 'onbeforeunload',
            'onfocus', 'onblur', 'onchange', 'oninput', 'onsubmit', 'onreset',
            'ondrag', 'ondragstart', 'ondragend', 'ondragenter', 'ondragleave', 'ondragover', 'ondrop',
            'onscroll', 'onresize', 'onwheel',
            'oncopy', 'oncut', 'onpaste',
            'onanimationstart', 'onanimationend', 'onanimationiteration',
            'ontransitionend', 'ontouchstart', 'ontouchmove', 'ontouchend', 'ontouchcancel',
            'onpointerdown', 'onpointerup', 'onpointermove', 'onpointerenter', 'onpointerleave',
            'formaction', 'xlink:href', 'xmlns'
        ],
        // Allowed CSS properties for style attribute
        ALLOWED_CSS: [
            'text-align', 'vertical-align', 'color', 'background-color',
            'font-weight', 'font-style', 'text-decoration',
            'margin', 'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
            'padding', 'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
            'border', 'border-top', 'border-right', 'border-bottom', 'border-left',
            'width', 'height', 'max-width', 'max-height', 'min-width', 'min-height',
            'display', 'visibility', 'opacity',
            'list-style', 'list-style-type'
        ],
        // Allowed URL schemes
        ALLOWED_URI_SCHEMES: ['http', 'https', 'mailto', 'tel', 'data'],
        // Allowed data: mime types for images
        ALLOWED_DATA_TYPES: ['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'image/svg+xml']
    };

    // Check if URL is safe
    function isSafeUrl(url, config) {
        if (!url) return true;
        
        const trimmedUrl = url.trim().toLowerCase();
        
        // Check for javascript: protocol
        if (trimmedUrl.startsWith('javascript:')) return false;
        if (trimmedUrl.startsWith('vbscript:')) return false;
        if (trimmedUrl.startsWith('data:') && !trimmedUrl.startsWith('data:image/')) return false;
        
        // Allow relative URLs
        if (trimmedUrl.startsWith('/') || trimmedUrl.startsWith('./') || trimmedUrl.startsWith('../')) return true;
        if (trimmedUrl.startsWith('#')) return true;
        
        // Check allowed schemes
        const schemes = config.ALLOWED_URI_SCHEMES || DEFAULT_CONFIG.ALLOWED_URI_SCHEMES;
        for (const scheme of schemes) {
            if (trimmedUrl.startsWith(scheme + ':')) return true;
        }
        
        // Allow URLs without scheme (relative)
        if (!trimmedUrl.includes(':')) return true;
        
        return false;
    }

    // Sanitize CSS
    function sanitizeStyle(style, config) {
        if (!style) return '';
        
        const allowedCss = config.ALLOWED_CSS || DEFAULT_CONFIG.ALLOWED_CSS;
        const sanitized = [];
        
        const declarations = style.split(';');
        for (const decl of declarations) {
            const parts = decl.split(':');
            if (parts.length === 2) {
                const prop = parts[0].trim().toLowerCase();
                const value = parts[1].trim();
                
                if (allowedCss.includes(prop)) {
                    // Check for dangerous values
                    if (!value.includes('expression') && 
                        !value.includes('javascript') && 
                        !value.includes('url(') &&
                        !value.includes('behavior')) {
                        sanitized.push(`${prop}: ${value}`);
                    }
                }
            }
        }
        
        return sanitized.join('; ');
    }

    // Check if tag is allowed
    function isAllowedTag(tagName, config) {
        const tag = tagName.toLowerCase();
        const forbidTags = config.FORBID_TAGS || DEFAULT_CONFIG.FORBID_TAGS;
        const allowedTags = config.ALLOWED_TAGS || DEFAULT_CONFIG.ALLOWED_TAGS;
        
        if (forbidTags.includes(tag)) return false;
        if (allowedTags.includes(tag)) return true;
        return false;
    }

    // Check if attribute is allowed
    function isAllowedAttr(attrName, config) {
        const attr = attrName.toLowerCase();
        const forbidAttr = config.FORBID_ATTR || DEFAULT_CONFIG.FORBID_ATTR;
        const allowedAttr = config.ALLOWED_ATTR || DEFAULT_CONFIG.ALLOWED_ATTR;
        
        // Always remove on* attributes
        if (attr.startsWith('on')) return false;
        if (forbidAttr.includes(attr)) return false;
        
        // Check data-* attributes
        if (attr.startsWith('data-')) {
            return allowedAttr.includes('data-*');
        }
        
        // Check aria-* attributes
        if (attr.startsWith('aria-')) {
            return allowedAttr.some(a => a.startsWith('aria-'));
        }
        
        return allowedAttr.includes(attr);
    }

    // Main sanitize function
    function sanitize(html, config) {
        if (!html) return '';
        if (typeof html !== 'string') {
            html = String(html);
        }
        
        const mergedConfig = { ...DEFAULT_CONFIG, ...config };
        
        // Create a temporary div to parse HTML
        const temp = document.createElement('div');
        temp.innerHTML = html;
        
        // Process all elements recursively
        function processNode(node) {
            if (node.nodeType === Node.TEXT_NODE) {
                return; // Text nodes are safe
            }
            
            if (node.nodeType !== Node.ELEMENT_NODE) {
                node.remove();
                return;
            }
            
            const tagName = node.tagName.toLowerCase();
            
            // Remove forbidden tags entirely
            if (!isAllowedTag(tagName, mergedConfig)) {
                // Keep text content for some tags
                const textContent = node.textContent;
                const textNode = document.createTextNode(textContent);
                node.parentNode.replaceChild(textNode, node);
                return;
            }
            
            // Process attributes
            const attributesToRemove = [];
            for (const attr of Array.from(node.attributes)) {
                const attrName = attr.name.toLowerCase();
                
                if (!isAllowedAttr(attrName, mergedConfig)) {
                    attributesToRemove.push(attr.name);
                    continue;
                }
                
                // Sanitize URL attributes
                if (['href', 'src', 'action', 'formaction', 'poster', 'background'].includes(attrName)) {
                    if (!isSafeUrl(attr.value, mergedConfig)) {
                        attributesToRemove.push(attr.name);
                        continue;
                    }
                }
                
                // Sanitize style attribute
                if (attrName === 'style') {
                    const sanitizedStyle = sanitizeStyle(attr.value, mergedConfig);
                    if (sanitizedStyle) {
                        node.setAttribute('style', sanitizedStyle);
                    } else {
                        attributesToRemove.push('style');
                    }
                }
                
                // Add rel="noopener noreferrer" to external links
                if (tagName === 'a' && attrName === 'href') {
                    const href = attr.value;
                    if (href && (href.startsWith('http://') || href.startsWith('https://'))) {
                        node.setAttribute('rel', 'noopener noreferrer');
                    }
                }
                
                // For input elements, only allow checkbox type
                if (tagName === 'input' && attrName === 'type') {
                    if (attr.value.toLowerCase() !== 'checkbox') {
                        attributesToRemove.push('type');
                    }
                }
            }
            
            // Remove disallowed attributes
            for (const attrName of attributesToRemove) {
                node.removeAttribute(attrName);
            }
            
            // Process children
            const children = Array.from(node.childNodes);
            for (const child of children) {
                processNode(child);
            }
        }
        
        // Process all top-level nodes
        const topNodes = Array.from(temp.childNodes);
        for (const node of topNodes) {
            processNode(node);
        }
        
        return temp.innerHTML;
    }

    // Add hooks system for extensibility
    const hooks = {
        beforeSanitize: [],
        afterSanitize: []
    };

    function addHook(hookName, fn) {
        if (hooks[hookName]) {
            hooks[hookName].push(fn);
        }
    }

    function removeHook(hookName, fn) {
        if (hooks[hookName]) {
            const index = hooks[hookName].indexOf(fn);
            if (index > -1) {
                hooks[hookName].splice(index, 1);
            }
        }
    }

    function removeAllHooks() {
        for (const hookName in hooks) {
            hooks[hookName] = [];
        }
    }

    return {
        sanitize: sanitize,
        addHook: addHook,
        removeHook: removeHook,
        removeAllHooks: removeAllHooks,
        isSupported: true,
        version: '1.0.0-custom'
    };
})();

// For compatibility with different module systems
if (typeof module !== 'undefined' && module.exports) {
    module.exports = DOMPurify;
}
